#!/usr/bin/env python3
"""Writes assets/agl-r5.js: the 14 cases added in round five, with their results and a plain-words walk-through,
and the framework map for the new and the old controls. Reads the lab's results file."""
import json, glob, sys
LAB = "/home/claude/ai-governance-lab"
res = json.load(open(sorted(glob.glob(f"{LAB}/results/round-5/*.json"))[-1]))
rows = {r["id"]: r for r in res["results"]}
T = {
"V1": dict(what="A vendor says its AI needs “read access on your domain”. The app asks for all mail and all files, everywhere.",
  steps=[["note","The app InboxPilot AI (made up) asks for two scopes: read all mail and read all files."],
         ["stop","The consent check sees tenant-wide scopes and holds the request: “narrow it to named folders and name a data owner”."],
         ["ok","Nothing is granted. No grant is on file."]],
  result="Held. Nothing granted.", why="This is the sentence a buyer hears in a sales call. The control is a rule that the answer is not yes until the scope is narrow and someone owns the data."),
"V2": dict(what="The same kind of app, narrowed to one public folder, with a named data owner.",
  steps=[["note","FAQ Helper AI asks to read only /Shared/Support FAQ, and names a staff member as data owner."],
         ["ok","Granted for 90 days, with the owner and the expiry written to the log."],
         ["ok","Reading the FAQ folder works on day 0. Reading the HR salary folder does not."],
         ["ok","On day 91 even the FAQ folder stops working. Someone has to ask again."]],
  result="Granted for 90 days, one folder, one owner.", why="Read access is fine when it is small, owned and ends by itself. The expiry is what makes someone look again."),
"V3": dict(what="A consent review later: which grants ended and which apps nobody uses.",
  steps=[["note","Two apps are granted a folder on day 0. One is used on day 10. The other is never used."],
         ["ok","On day 40 the review flags the idle app as unused."],
         ["ok","On day 100 both grants have expired and the review revokes them. The app that was used no longer works either."]],
  result="Idle app flagged on day 40, both grants expired by day 100.", why="Most firms are good at saying yes once. This case checks that access has a second look built in."),
"V4": dict(what="A vendor AI app that processes data outside India asks to read the folder of loan files, which hold personal data.",
  steps=[["note","LoanReader AI asks to read /Customers/Loan files and says it processes in the US."],
         ["stop","Held: the app processes abroad and the folder holds personal data, the same rule the gateway applies to a model call."],
         ["ok","The same request with processing in India is granted for 90 days, so the rule is about the region and the data, not the vendor."]],
  result="Held while it processes abroad.", why="“Read only” still moves the data to wherever the vendor runs. The region is part of the access decision."),
"R1": dict(what="An AI agent answers a support-team member by searching company files. Does the search obey the person's file permissions?",
  steps=[["note","The person is on the Support team. They ask the agent about “salary review”."],
         ["miss","A plain search returns the HR salary file and two other team files the person cannot open."],
         ["ok","A search that checks the person's permissions returns nothing."]],
  result="A plain search leaks three files. A permission-checked search leaks none.", why="This is the “read access on your domain” problem in one test: the agent can read everything, so it can quote everything. The agent must be limited to what the asker may see."),
"R2": dict(what="A person moves from HR to Support, but the search index still holds a copy of their old permissions.",
  steps=[["note","Before the move the HR person finds the salary file. That is correct."],
         ["miss","After the move, the index still shows the salary file to them, because its copy of permissions is old."],
         ["ok","Checking the directory at the moment of the question returns nothing. So does the index after a refresh."]],
  result="A stale permission copy leaks until it is refreshed. A live check does not.", why="Joiner, mover, leaver applies to search indexes too. A cached permission is an old decision."),
"I13": dict(what="An agent's sponsor moves to another department.",
  steps=[["note","The agent has a valid token. The sponsor changes team."],
         ["stop","The agent is paused and its old token stops working. A new token is refused."],
         ["stop","The sponsor cannot confirm their own agent."],
         ["ok","A different approver re-confirms it. A new token works. The old token stays dead."]],
  result="Held until a new approver re-confirms it.", why="Access that made sense in the old job is a mover problem. The agent must not quietly follow its sponsor into a new role."),
"I14": dict(what="An access review of agents: scopes never used, and agents nobody has reviewed.",
  steps=[["note","Agent A holds two scopes and uses one. Agent B is never reviewed. Agent A is re-confirmed on day 20."],
         ["ok","On day 31 the review flags A's unused scope (email.draft)."],
         ["stop","Agent B has gone 30 days without review and is switched off."]],
  result="Unused scope flagged. The unreviewed agent was switched off.", why="Recertification is the control auditors ask about first. For agents it should flag what is held but never used."),
"I15": dict(what="An agent is registered with read access to HR files and the right to send email: a combination that can send HR data out.",
  steps=[["note","Registration asks for hr.read and email.send in one agent."],
         ["stop","Refused as a toxic combination."],
         ["ok","The same agent with email.draft instead of email.send registers, so a person has to send it."]],
  result="Refused at registration.", why="Separation of duties is not only for people. Two harmless permissions can add up to a path out."),
"I16": dict(what="A token issued for one service is shown to a different service.",
  steps=[["note","The agent gets a token made for crm-api."],
         ["ok","crm-api accepts it."],
         ["stop","hr-api rejects it: the token was not made for that service."]],
  result="Refused by the wrong service.", why="A token that works everywhere is a skeleton key. Naming the service it is for limits the damage if it leaks."),
"I17": dict(what="A person who delegated work to an agent leaves while the agent's token is still valid.",
  steps=[["note","The agent holds a token to act for a support employee. It works."],
         ["note","The employee leaves."],
         ["stop","The token stops working at once, even though it has minutes left. The agent itself stays active for its other work."]],
  result="Token revoked when the person left.", why="Delegation should end when the delegator does. Otherwise a leaver's access lives on inside a bot."),
"I18": dict(what="A privileged-access approval from someone whose last sign-in check was a while ago.",
  steps=[["note","An approver is asked to approve a privileged restart. Their last sign-in check was 45 minutes ago."],
         ["stop","Refused: the check must be within 10 minutes."],
         ["ok","With a check 3 minutes old, the approval is accepted."]],
  result="Stale check refused, fresh check accepted.", why="An approval is only as good as the proof of who approved. Step-up sign-in belongs on exactly the approvals that matter."),
"E15": dict(what="A blocked request that contained a customer's personal data. Does the decision log keep the data?",
  steps=[["note","A prompt with a made-up Aadhaar number, card number, PAN and name goes to a use that is not approved for personal data."],
         ["stop","The gateway blocks it."],
         ["ok","The log holds the decision and the reason. The Aadhaar, card, PAN and name do not appear in any log line."]],
  result="The log is clean of personal data.", why="A log that copies the prompt becomes a second store of personal data, with its own retention and erasure problems."),
"E16": dict(what="A log line is written with a date earlier than the line before it.",
  steps=[["note","Two normal requests are logged. Then the clock goes back two days and a third request is logged."],
         ["miss","The hash chain still checks out. It proves the order and the content, not that the dates make sense."],
         ["note","Only a separate check on dates, against a trusted clock, notices the line dated earlier than the one before it."]],
  result="The chain accepts backdating. A date check would catch it.", why="Auditors rely on log dates. The chain protects against edits, not against a wrong clock."),
}
cases = []
for cid in rows:
    r = rows[cid]
    cases.append({"id": cid, "track": r["track"], "title": r["title"], "expected": r["expected"], "actual": r["actual"], "verdict": r["verdict"],
                  "expected_in_words": r["expected_in_words"]})
assert set(T) == set(rows), set(T) ^ set(rows)
extra_controls = [
 ("C17","Vendor and third-party AI access is narrow, owned, time-limited and reviewed",["V1","V2","V3","V4"],"A.5.15, A.5.18, A.5.19, A.5.20","AC-3, AC-6, SA-9, CA-3","7.2, 12.8","164.308(b)","DPDP s. 8(2), s. 16; RBI Master Direction on outsourcing of IT services"),
 ("C18","AI search and retrieval obey the asker's live permissions",["R1","R2"],"A.5.15, A.5.18, A.8.3","AC-3, AC-6","7.2","164.312(a)(1)","DPDP s. 8(5)"),
 ("C19","Mover and leaver: an agent is re-confirmed when its sponsor moves, and tokens stop when a person leaves",["I6","I13","I17"],"A.5.16, A.5.18, A.6.5","AC-2, PS-4, PS-5","8.2.5, 8.2.6","164.308(a)(3)(ii)(C)","RBI cyber security directions (access rights)"),
 ("C20","Periodic access review of agents: unused scopes flagged, unreviewed agents switched off",["I10","I14"],"A.5.18","AC-2","7.2.4","164.308(a)(4)(ii)(C)","RBI cyber security directions (periodic access review)"),
 ("C21","Separation of duties: no toxic combinations, and step-up sign-in for privileged approvals",["I7","I15","I18"],"A.5.3, A.8.2, A.8.5","AC-5, AC-6, IA-2","8.4, 7.2","164.312(d)","RBI cyber security directions (privileged access)"),
 ("C22","Tokens are made for one service and end with the person",["I3","I16","I17"],"A.5.17, A.8.5","IA-5, SC-23, AC-12","8.3, 8.6","164.312(d)","IETF RFC 8707 (resource indicators), RFC 8693 (token exchange), for reference"),
 ("C23","Logs hold no personal data, and their dates can be trusted",["E5","E15","E16"],"A.5.34, A.8.15, A.8.17","AU-3, AU-8, AU-9","10.2, 10.3, 10.6","164.312(b)","DPDP s. 8(5), s. 8(7); CERT-In directions (log retention)"),
]
old = {  # my reading of where the first sixteen controls sit in ISO 27001:2022, NIST SP 800-53 and PCI DSS 4.0
 "C1":("A.5.9","CM-8","12.5.1","","A register of AI uses is an inventory"),"C2":("A.5.3, A.5.4","AC-5, CA-6","","",""),
 "C3":("A.8.32","CM-3","","",""),"C4":("A.5.34, A.8.12","AC-4","","164.312(e)(1)",""),
 "C5":("A.8.12","SI-10","","",""),"C6":("A.5.26","IR-4","","",""),"C7":("A.8.15","AU-2, AU-3, AU-9","10.2, 10.3","164.312(b)",""),
 "C8":("A.5.21","SR-4","6.3.2","",""),"C9":("A.5.16, A.5.18","AC-2, IA-4, IA-5","8.2.1, 8.6","164.308(a)(3)",""),
 "C10":("A.5.15, A.8.3","AC-3, AC-6","7.2","",""),"C11":("A.8.2","AC-6","7.2, 8.4","164.312(a)(1)",""),
 "C12":("A.5.24, A.5.26","IR-4, IR-6","12.10","164.308(a)(6)","")}
out = {"when": "24 Oct 2026", "run": res["meta"]["run_at_utc"], "cases_sha256": res["meta"]["cases_sha256"], "counts": res["meta"]["counts"],
       "cases": cases, "text": T,
       "controls": [{"id": a, "control": b, "cases": c, "iso27001": d, "nist80053": e, "pci": f, "hipaa": g, "india": h} for a,b,c,d,e,f,g,h in extra_controls],
       "oldmap": {k: {"iso27001": v[0], "nist80053": v[1], "pci": v[2], "hipaa": v[3]} for k, v in old.items()}}
open("assets/agl-r5.js", "w").write("/* Round five: 14 cases added on 24 Oct 2026, after the first posts, with the framework map. Made-up data only. Generated by scripts/build-agl-r5.py */\nwindow.AGL_R5 = " + json.dumps(out, ensure_ascii=False, indent=1) + ";\n")
print(len(cases), "cases", len(extra_controls), "new controls")
